test("ChatView.create and destroy manage websocket lifecycle", () => {
  const container = { textContent: "", addEventListener() {}, removeEventListener() {} };
  let closed = false;

  class RecordingWebSocket {
    constructor(url) {
      this.url = url;
      this.readyState = 1;
      this.OPEN = 1;
      this.CONNECTING = 0;
      this.listeners = {};
    }

    addEventListener(type, handler) {
      this.listeners[type] = handler;
    }

    removeEventListener(type) {
      delete this.listeners[type];
    }

    close() {
      closed = true;
      this.readyState = 3;
    }
  }

  const priorWebSocket = globalThis.WebSocket;
  globalThis.WebSocket = RecordingWebSocket;

  try {
    const handle = ChatView.create(container, "ws://example.test/stream");
    assert.ok(handle.state);
    assert.equal(container.textContent.includes("status=loading"), true);

    handle._owned.socket.listeners.message({
      data: JSON.stringify({
        type: "events",
        events: [
          { type: "TEXT_MESSAGE_START", messageId: "live", role: "assistant" },
          { type: "TEXT_MESSAGE_CONTENT", messageId: "live", delta: "ok" },
          { type: "TEXT_MESSAGE_END", messageId: "live" },
        ],
      }),
    });
    assert.equal(MessageContent(handle.state, "live"), "ok");

    ChatView.destroy(handle);
    assert.equal(closed, true);
    assert.equal(container.textContent, "");
  } finally {
    globalThis.WebSocket = priorWebSocket;
  }
});

