  class RecordingWebSocket {
    constructor(url) {
      this.url = url;
      this.readyState = 1;
      this.OPEN = 1;
      this.CONNECTING = 0;
      this.listeners = {};
    }

    addEventListener(type, handler) {
      this.listeners[type] = handler;
    }

    removeEventListener(type) {
      delete this.listeners[type];
    }

    close() {
      closed = true;
      this.readyState = 3;
    }
