  ReduceAll(state, [
    { type: "TEXT_MESSAGE_START", messageId, role: "assistant" },
    { type: "TEXT_MESSAGE_CONTENT", messageId, delta: "Hello " },
    { type: "TEXT_MESSAGE_CONTENT", messageId, delta: "world" },
    { type: "TEXT_MESSAGE_END", messageId },
